<?php require __DIR__.'/../bootstrap.php';admin_only();verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$pairs=['shipping_cost'=>max(0,(int)$_POST['shipping_cost']),'site_name'=>trim($_POST['site_name']),'support_text'=>trim($_POST['support_text'])];$st=$pdo->prepare('INSERT INTO settings(`key`,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)');foreach($pairs as $k=>$v)$st->execute([$k,$v]);flash('ok','تنظیمات ذخیره شد.');redirect('admin/settings.php');}$title='تنظیمات';require __DIR__.'/../partials/header.php';?><h1>تنظیمات فروشگاه</h1><div class="panel"><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="field"><label>نام سایت</label><input name="site_name" value="<?=e(setting('site_name','SHOPX'))?>"></div><div class="field"><label>هزینه ارسال</label><input type="number" name="shipping_cost" value="<?=e(setting('shipping_cost','0'))?>"></div><div class="field"><label>متن پشتیبانی</label><textarea name="support_text" rows="4"><?=e(setting('support_text','پشتیبانی فروشگاه'))?></textarea></div><button class="btn">ذخیره</button></form></div><?php require __DIR__.'/../partials/footer.php'; ?>
